export interface ProductionBatch {
  batchId: string;
  productCode: string;
  units: number;
  inspected: boolean;
}

function validateBatch(batch: ProductionBatch): void {
  if (
    batch.batchId.length === 0 ||
    batch.productCode.length === 0 ||
    !Number.isSafeInteger(batch.units) ||
    batch.units < 0
  ) {
    throw new TypeError('invalid batch');
  }
}

export class BatchRegistry {
  private readonly batches = new Map<string, ProductionBatch>();

  public add(batch: ProductionBatch): void {
    validateBatch(batch);
    if (this.batches.has(batch.batchId)) throw new Error('duplicate batchId');
    this.batches.set(batch.batchId, { ...batch });
  }

  public replace(batchId: string, replacement: ProductionBatch): boolean {
    if (!this.batches.has(batchId)) return false;
    validateBatch(replacement);
    if (replacement.batchId !== batchId) throw new Error('batchId mismatch');
    this.batches.set(batchId, { ...replacement });
    return true;
  }

  public get(batchId: string): ProductionBatch;
  public get(batchId: string): ProductionBatch | undefined {
    return this.batches.get(batchId);
  }

  public remove(batchId: string): boolean {
    return this.batches.delete(batchId);
  }

  public list(): ProductionBatch[] {
    return Array.from(this.batches.values(), (batch) => ({ ...batch }));
  }
}

