import { BatchRegistry } from './solution';
import type { ProductionBatch } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}

function throwsAs(action: () => void, constructor: typeof Error, message: string): void {
  try {
    action();
  } catch (error) {
    if (error instanceof constructor) return;
    throw new Error(`${message}: wrong exception type`);
  }
  throw new Error(`${message}: expected exception`);
}

const registry = new BatchRegistry();
equal(registry.get('missing'), undefined, 'missing get');
equal(registry.remove('missing'), false, 'missing remove');
equal(JSON.stringify(registry.list()), '[]', 'initial list');

const first: ProductionBatch = { batchId: 'b1', productCode: 'p1', units: 0, inspected: false };
registry.add(first);
first.productCode = 'mutated';
first.units = 99;
first.inspected = true;
equal(JSON.stringify(registry.get('b1')), JSON.stringify({ batchId: 'b1', productCode: 'p1', units: 0, inspected: false }), 'add copies input');

registry.add({ batchId: 'b2', productCode: ' ', units: Number.MAX_SAFE_INTEGER, inspected: true });
equal(JSON.stringify(registry.list().map((batch) => batch.batchId)), JSON.stringify(['b1', 'b2']), 'insertion order');
throwsAs(() => registry.add({ batchId: 'b1', productCode: 'other', units: 1, inspected: true }), Error, 'duplicate ID');

const retrieved1 = registry.get('b1');
const retrieved2 = registry.get('b1');
assert(retrieved1 !== undefined && retrieved2 !== undefined, 'existing batch must be returned');
assert(retrieved1 !== retrieved2, 'each get must return a fresh copy');
retrieved1.productCode = 'external';
retrieved1.units = 200;
equal(retrieved2.productCode, 'p1', 'get copies are isolated');
equal(registry.get('b1')?.units, 0, 'get mutation cannot alter registry');

const listed1 = registry.list();
const listed2 = registry.list();
assert(listed1 !== listed2, 'list arrays must be fresh');
assert(listed1[0] !== listed2[0], 'listed entries must be fresh');
listed1.reverse();
listed1[0].productCode = 'external';
equal(JSON.stringify(registry.list().map((batch) => batch.batchId)), JSON.stringify(['b1', 'b2']), 'list mutation cannot alter order');
equal(registry.get('b2')?.productCode, ' ', 'list entry mutation cannot alter state');

const replacement: ProductionBatch = { batchId: 'b1', productCode: 'new', units: 7, inspected: true };
equal(registry.replace('b1', replacement), true, 'successful replace');
replacement.productCode = 'changed later';
equal(registry.get('b1')?.productCode, 'new', 'replace copies input');
equal(JSON.stringify(registry.list().map((batch) => batch.batchId)), JSON.stringify(['b1', 'b2']), 'replace retains position');
equal(registry.replace('absent', { batchId: '', productCode: '', units: -1, inspected: false }), false, 'missing replace does not validate or mutate');
throwsAs(() => registry.replace('b1', { batchId: 'other', productCode: 'valid', units: 1, inspected: false }), Error, 'replacement ID must match');
throwsAs(() => registry.replace('b1', { batchId: 'b1', productCode: '', units: 1, inspected: false }), TypeError, 'replacement must be valid');
equal(registry.get('b1')?.productCode, 'new', 'failed replacements do not mutate');

for (const invalid of [
  { batchId: '', productCode: 'p', units: 0, inspected: false },
  { batchId: 'x', productCode: '', units: 0, inspected: false },
  { batchId: 'x', productCode: 'p', units: -1, inspected: false },
  { batchId: 'x', productCode: 'p', units: 1.5, inspected: false },
  { batchId: 'x', productCode: 'p', units: NaN, inspected: false },
  { batchId: 'x', productCode: 'p', units: Number.MAX_SAFE_INTEGER + 1, inspected: false },
]) {
  throwsAs(() => registry.add(invalid), TypeError, 'invalid batch');
}

assert(registry.remove('b1'), 'existing remove returns true');
equal(registry.remove('b1'), false, 'second remove returns false');
registry.add({ batchId: 'b1', productCode: 'readded', units: 3, inspected: false });
equal(JSON.stringify(registry.list().map((batch) => batch.batchId)), JSON.stringify(['b2', 'b1']), 're-added ID goes to end');

